fn remove_duplicates(nums: &Vec<i32>) -> usize {
    // If the input vector is empty, there are no distinct values.
    if nums.is_empty() {
        return 0;
    }

    // At least one value exists, so start the count at 1.
    let mut distinct_count = 1;

    // Iterate from the second element onward, comparing with the previous.
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            distinct_count += 1;
        }
    }

    distinct_count
}

